import pkg from '/Users/aashanjaved/.vscode/extensions/danielsanmedium.dscodegpt-3.24.71/standalone/node_modules/patchright/index.js';
const { chromium } = pkg;
const b=await chromium.launch({headless:true});
const p=await (await b.newContext({viewport:{width:1280,height:900}})).newPage();
await p.goto('http://127.0.0.1:18080/',{waitUntil:'networkidle'});
await p.waitForTimeout(600);
const r=await p.evaluate(()=>{
  const out=[];
  document.querySelectorAll('*').forEach(e=>{
    const t=(e.textContent||'').trim();
    if(t!=='Zum Anker')return;
    const rc=e.getBoundingClientRect();
    out.push({tag:e.tagName.toLowerCase(),parent:e.parentElement?e.parentElement.tagName.toLowerCase():null,
      parentTid:e.parentElement?e.parentElement.getAttribute('data-testid'):null,
      box:[rc.x,rc.y,rc.width,rc.height], display:getComputedStyle(e).display,
      visibility:getComputedStyle(e).visibility});});
  // is a zero box intrinsic to <option> regardless of styling?
  const o=document.createElement('option'); o.textContent='probe';
  document.querySelector('select').appendChild(o);
  const pr=o.getBoundingClientRect();
  return {zumAnker:out, freshOptionBox:[pr.width,pr.height]};
});
console.log(JSON.stringify(r,null,1));
await b.close();
EOF
